def __init__(
    self,
    charset: str = "utf-8",
    env: cabc.Mapping[str, str | None] | None = None,
    echo_stdin: bool = False,
    catch_exceptions: bool = True,
    capture: CaptureMode = "sys",
) -> None:
    if capture not in {"sys", "fd"}:
        raise ValueError(
            f"capture={capture!r} is not valid. Choose from 'sys' or 'fd'."
        )
    if capture == "fd" and sys.platform == "win32":
        raise ValueError(
            f"capture={capture!r} is not supported on Windows. Use 'sys'."
        )
    self.charset = charset
    self.env = env or {}
    self.echo_stdin = echo_stdin
    self.catch_exceptions = catch_exceptions
    self.capture = capture

def pass_context(f: t.Callable[te.Concatenate[Context, P], R]) -> t.Callable[P, R]:
    """Marks a callback as wanting to receive the current context
    object as first argument.
    """

    def new_func(*args: P.args, **kwargs: P.kwargs) -> R:
        return f(get_current_context(), *args, **kwargs)

    return update_wrapper(new_func, f)

def shell_complete(self, ctx: Context, incomplete: str) -> list[CompletionItem]:
    """Return a list of completions for the incomplete value. Looks
    at the names of options and chained multi-commands.

    Any command could be part of a chained multi-command, so sibling
    commands are valid at any point during command completion.

    :param ctx: Invocation context for this command.
    :param incomplete: Value being completed. May be empty.

    .. versionadded:: 8.0
    """
    from click.shell_completion import CompletionItem

    results: list[CompletionItem] = []

    if incomplete and not incomplete[0].isalnum():
        for param in self.get_params(ctx):
            if (
                not isinstance(param, Option)
                or param.hidden
                or (
                    not param.multiple
                    and ctx.get_parameter_source(param.name)
                    is ParameterSource.COMMANDLINE
                )
            ):
                continue

            results.extend(
                CompletionItem(name, help=param.help)
                for name in [*param.opts, *param.secondary_opts]
                if name.startswith(incomplete)
            )

    while ctx.parent is not None:
        ctx = ctx.parent

        if isinstance(ctx.command, Group) and ctx.command.chain:
            results.extend(
                CompletionItem(name, help=command.get_short_help_str())
                for name, command in _complete_visible_commands(ctx, incomplete)
                if name not in ctx._protected_args
            )

    return results

"""

# Compatible with Windows PowerShell 5.1+ and PowerShell (pwsh) 7+.
# Uses Register-ArgumentCompleter -Native, which receives the command AST
# as parsed by PowerShell. The command text is forwarded verbatim through
# COMP_WORDS so the Python side can reuse the same shlex-based splitting
# used by the bash/zsh completers.
_SOURCE_POWERSHELL = """\
Register-ArgumentCompleter -Native -CommandName %(prog_name)s -ScriptBlock {
    param($wordToComplete, $commandAst, $cursorPosition)

    $prev_complete = $env:%(complete_var)s
    $prev_words = $env:COMP_WORDS
    $prev_cword = $env:COMP_CWORD

    $env:%(complete_var)s = 'powershell_complete'
    $env:COMP_WORDS = $commandAst.ToString()
    if ($wordToComplete) {
        $env:COMP_CWORD = $commandAst.CommandElements.Count - 1
    } else {
        $env:COMP_CWORD = $commandAst.CommandElements.Count
    }

    try {
        $response = & %(prog_name)s 2>$null
    } finally {
        $env:%(complete_var)s = $prev_complete
        $env:COMP_WORDS = $prev_words
        $env:COMP_CWORD = $prev_cword
    }

    if (-not $response) { return }

    $prefix = "$wordToComplete*"
    $lines = $response -split "`n"
    for ($i = 0; $i + 2 -lt $lines.Count; $i += 3) {
        $type = $lines[$i]
        $value = $lines[$i + 1]
        $descr = $lines[$i + 2]
        if (-not $type) { continue }

        if ($type -eq 'plain') {
            $tip = if ($descr -and $descr -ne '_') { $descr } else { $value }
            [System.Management.Automation.CompletionResult]::new(
                $value, $value, 'ParameterValue', $tip)
        } elseif ($type -eq 'dir') {
            Get-ChildItem -Directory -Path $prefix -ErrorAction SilentlyContinue |
                ForEach-Object {
                    [System.Management.Automation.CompletionResult]::new(
                        $_.FullName, $_.Name, 'ProviderContainer', $_.FullName)
                }
        } elseif ($type -eq 'file') {
            Get-ChildItem -Path $prefix -ErrorAction SilentlyContinue |
                ForEach-Object {
                    $kind = 'ProviderItem'
                    if ($_.PSIsContainer) { $kind = 'ProviderContainer' }
                    [System.Management.Automation.CompletionResult]::new(
                        $_.FullName, $_.Name, $kind, $_.FullName)
                }
        }
    }
}
"""

def _is_incomplete_option(ctx: Context, args: list[str], param: Parameter) -> bool:
    """Determine if the given parameter is an option that needs a value.

    :param args: List of complete args before the incomplete value.
    :param param: Option object being checked.
    """
    if not isinstance(param, Option):
        return False

    if param.is_flag or param.count:
        return False

    last_option = None

    for index, arg in enumerate(reversed(args)):
        if index + 1 > param.nargs:
            break

        if _start_of_option(ctx, arg):
            last_option = arg
            break

    return last_option is not None and last_option in param.opts

def get_completion_args(self) -> tuple[list[str], str]:
    cwords = split_arg_string(os.environ["COMP_WORDS"])
    cword = int(os.environ["COMP_CWORD"])
    args = cwords[1:cword]

    try:
        incomplete = cwords[cword]
    except IndexError:
        incomplete = ""

    return args, incomplete

        completions, then calls :meth:`format_completion` for each
        completion.
        """
        args, incomplete = self.get_completion_args()
        completions = self.get_completions(args, incomplete)
        out = [self.format_completion(item) for item in completions]
        return "\n".join(out)


class BashComplete(ShellComplete):
    """Shell completion for Bash."""

    name: t.ClassVar[str] = "bash"
    source_template: t.ClassVar[str] = _SOURCE_BASH

    @staticmethod
    def _check_version() -> None:
        import shutil
        import subprocess

        bash_exe = shutil.which("bash")

        if bash_exe is None:
            match = None
        else:
            output = subprocess.run(
                [bash_exe, "--norc", "-c", 'echo "${BASH_VERSION}"'],
                stdout=subprocess.PIPE,
            )
            match = re.search(r"^(\d+)\.(\d+)\.\d+", output.stdout.decode())

        if match is not None:
            major, minor = match.groups()

            if major < "4" or major == "4" and minor < "4":
                echo(
                    _(
                        "Shell completion is not supported for Bash"
                        " versions older than 4.4."
                    ),
                    err=True,
                )
        else:
            echo(
                _("Couldn't detect Bash version, shell completion is not supported."),
                err=True,
            )

    def source(self) -> str:
        self._check_version()
        return super().source()

    def get_completion_args(self) -> tuple[list[str], str]:
        cwords = split_arg_string(os.environ["COMP_WORDS"])
        cword = int(os.environ["COMP_CWORD"])
        args = cwords[1:cword]

        try:
            incomplete = cwords[cword]
        except IndexError:
            incomplete = ""

        return args, incomplete

    def format_completion(self, item: CompletionItem[t.Any]) -> str:
        return f"{item.type},{item.value}"


class ZshComplete(ShellComplete):
    """Shell completion for Zsh."""

    name: t.ClassVar[str] = "zsh"
    source_template: t.ClassVar[str] = _SOURCE_ZSH

def forward(self, cmd: Command, /, *args: t.Any, **kwargs: t.Any) -> t.Any:
    """Similar to :meth:`invoke` but fills in default keyword
    arguments from the current context if the other command expects
    it.  This cannot invoke callbacks directly, only other commands.

    .. versionchanged:: 8.0
        All ``kwargs`` are tracked in :attr:`params` so they will be
        passed if ``forward`` is called at multiple levels.
    """
    # Can only forward to other commands, not direct callbacks.
    if not isinstance(cmd, Command):
        raise TypeError("Callback is not a command.")

    for param in self.params:
        if param not in kwargs:
            kwargs[param] = self.params[param]

    return self.invoke(cmd, *args, **kwargs)

def type_cast_value(self, ctx: Context, value: t.Any) -> t.Any:
    """Convert and validate a value against the parameter's
    :attr:`type`, :attr:`multiple`, and :attr:`nargs`.
    """
    if value is None:
        if self.multiple or self.nargs == -1:
            return ()
        else:
            return value

    def check_iter(value: t.Any) -> cabc.Iterator[t.Any]:
        try:
            return _check_iter(value)
        except TypeError:
            # This should only happen when passing in args manually,
            # the parser should construct an iterable when parsing
            # the command line.
            raise BadParameter(
                _("Value must be an iterable."), ctx=ctx, param=self
            ) from None

    # Define the conversion function based on nargs and type.

    if self.nargs == 1 or self.type.is_composite:

        def convert(value: t.Any) -> t.Any:
            return self.type(value, param=self, ctx=ctx)

    elif self.nargs == -1:

        def convert(value: t.Any) -> t.Any:  # tuple[t.Any, ...]
            return tuple(self.type(x, self, ctx) for x in check_iter(value))

    else:  # nargs > 1

        def convert(value: t.Any) -> t.Any:  # tuple[t.Any, ...]
            value = tuple(check_iter(value))

            if len(value) != self.nargs:
                raise BadParameter(
                    ngettext(
                        "Takes {nargs} values but 1 was given.",
                        "Takes {nargs} values but {len} were given.",
                        len(value),
                    ).format(nargs=self.nargs, len=len(value)),
                    ctx=ctx,
                    param=self,
                )

            return tuple(self.type(x, self, ctx) for x in value)

    if self.multiple:
        return tuple(convert(x) for x in check_iter(value))

    return convert(value)

@abstractmethod
def _parse_decls(
    self, decls: cabc.Sequence[str], expose_value: bool
) -> tuple[str, list[str], list[str]]: ...

def process(self, value: t.Any, state: _ParsingState) -> None:
    if self.action == "store":
        state.opts[self.dest] = value  # type: ignore
    elif self.action == "store_const":
        state.opts[self.dest] = self.const  # type: ignore
    elif self.action == "append":
        state.opts.setdefault(self.dest, []).append(value)  # type: ignore
    elif self.action == "append_const":
        state.opts.setdefault(self.dest, []).append(self.const)  # type: ignore
    elif self.action == "count":
        state.opts[self.dest] = state.opts.get(self.dest, 0) + 1  # type: ignore
    else:
        raise ValueError(f"unknown action '{self.action}'")
    state.order.append(self.obj)

