		retry: inheritedRetry,
		fetch: async () => new Response(fixture),
	});
	const child = parent.extend({
		retry: {
			limit: undefined,
			methods: undefined,
			statusCodes: undefined,
			afterStatusCodes: undefined,
			maxRetryAfter: undefined,
			backoffLimit: undefined,
			retryOnTimeout: undefined,
