					? new Response(null, {status: 429, headers: {'Retry-After': '2000'}})
					: new Response(fixture);
			},
			retry: {
				limit: 1,
				backoffLimit: 50,
			},
		}).text(), fixture);

		t.true(scheduledDelays.includes(retryAfterDelay));
		t.false(scheduledDelays.includes(50));
	});

	t.is(requestCount, 2);
});

